#!/usr/bin/env bash
# Blocks tool/AI attribution in anything that reaches GitHub: "Co-Authored-By:" trailers,
# "Generated by/with ..." footers and any mention of the assistant's name.
#
#   bin/check-attribution.sh file  <path>        # one commit message file (commit-msg hook)
#   bin/check-attribution.sh range <rev-range>   # every commit message in a range, e.g. origin/main..HEAD
#   bin/check-attribution.sh text  [label]       # arbitrary text on stdin (PR title/body in CI)
#
# Exit 0 = clean, 1 = forbidden text found (offending lines are printed).
set -euo pipefail

PATTERN='co-authored-by:|generated[[:space:]]+(by|with)|cl''aude'

scan() { # $1 = label, stdin = text
	local hits
	hits="$(grep -inE "$PATTERN" || true)"
	if [ -n "$hits" ]; then
		echo "✖ Forbidden attribution in $1:" >&2
		printf '%s\n' "$hits" | sed 's/^/    /' >&2
		return 1
	fi
}

mode="${1:-}"
case "$mode" in
	file)
		# Ignore the comment lines git adds to the message template.
		grep -v '^#' "${2:?message file required}" | scan "commit message"
		;;
	range)
		range="${2:?revision range required}"
		failed=0
		for sha in $(git rev-list "$range"); do
			git log -1 --format=%B "$sha" | scan "commit $(git log -1 --format='%h %s' "$sha")" || failed=1
		done
		exit "$failed"
		;;
	text)
		scan "${2:-text}"
		;;
	*)
		sed -n '2,8p' "$0" >&2
		exit 2
		;;
esac
